{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <div class="brand">
      <h1 class="brand-name">{{BUSINESS_NAME}}</h1>
      <p class="tagline">{{TAGLINE}}</p>
    </div>
    <nav class="main-nav" aria-label="Primary">
      <ul>
        <li><a href="events.html">Gatherings</a></li>
        <li><a href="private-sessions.html">Private</a></li>
        <li><a href="pricing.html">Investment</a></li>
        <li><a href="about.html">Story</a></li>
        <li><a href="faq.html">Help</a></li>
        <li><a class="cta" href="book.html">Book a spot</a></li>
        <li><a href="contact.html">Connect</a></li>
      </ul>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div class="hero-inner">
        <h2 class="hero-title">An evening shaped by careful tones</h2>
        <p class="hero-sub">{{TAGLINE}}</p>
        <div class="hero-actions">
          <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <button id="try-it-btn" class="btn btn-outline">Try a short practice</button>
        </div>
      </div>
      <div class="hero-decor" aria-hidden="true"></div>
    </section>

    <section id="next-gathering" class="next-event">
      <h3 class="section-title">Next gathering</h3>
      <div class="event-card">
        <div class="event-meta">
          <p class="event-date">Sat, Mar 6 • 7:00pm</p>
          <p class="event-venue">{{CITY}}, {{STATE}}</p>
        </div>
        <div class="seat-selector">
          <label for="seat-count">Reserve seats</label>
          <div class="seat-controls">
            <button id="seat-decrease" class="seat-btn" aria-label="Decrease seats">−</button>
            <input id="seat-count" type="number" value="1" min="1" max="12" aria-label="Number of seats">
            <button id="seat-increase" class="seat-btn" aria-label="Increase seats">+</button>
            <span id="seats-available" class="seats-available">12 seats left</span>
          </div>
          <div class="seat-actions">
            <button id="reserve-btn" class="btn">Reserve (local)</button>
          </div>
          <p class="helper small">This is a local reservation flow for demo; final booking happens when you confirm on the next page.</p>
        </div>
      </div>
    </section>

    <section class="myth-truth">
      <h3 class="section-title">Common assumptions — examined</h3>
      <div class="columns">
        <div class="card">
          <h4>Myth: Sound is just background</h4>
          <p>Truth: Specific vibrations direct attention and support nervous-system downshifts when organized with care.</p>
        </div>
        <div class="card">
          <h4>Myth: You need experience</h4>
          <p>Truth: We design entry points for first-timers and seasoned listeners alike — no prior knowledge required.</p>
        </div>
      </div>
    </section>

    <section class="pillars">
      <h3 class="section-title">Our guiding ways</h3>
      <ul>
        <li><strong>Attune:</strong> precise listening to what the room needs</li>
        <li><strong>Steady:</strong> reliable structures for safety and ease</li>
        <li><strong>Warmth:</strong> an inviting container for rest</li>
      </ul>
    </section>

    <section class="case-notes">
      <h3 class="section-title">Case notes</h3>
      <article class="note">
        <p>“A careful pause — where I could let the day unspool.” — M.</p>
      </article>
      <article class="note">
        <p>“I left steadier in my shoulders and lighter in my thinking.” — R.</p>
      </article>
    </section>

    <section class="what-to-bring">
      <h3 class="section-title">What to bring — make it easier</h3>
      <form id="packing-form">
        <div class="grid">
          <label><input type="checkbox" name="item" value="blanket"> Blanket or warm layers</label>
          <label><input type="checkbox" name="item" value="mat"> Yoga mat or cushion</label>
          <label><input type="checkbox" name="item" value="pillow"> Small neck pillow</label>
          <label><input type="checkbox" name="item" value="mask"> Eye covering</label>
          <label><input type="checkbox" name="item" value="water"> Bottle of water</label>
          <label><input type="checkbox" name="item" value="notes"> Pen & small notebook</label>
        </div>
        <div class="form-actions">
          <button id="generate-pack" class="btn">Generate packing list</button>
          <button id="suggested-pack" class="btn btn-outline">Quick suggestions</button>
        </div>
      </form>
      <div id="pack-output" class="pack-output" aria-live="polite"></div>
    </section>

    <section class="faq-preview">
      <h3 class="section-title">Questions people ask</h3>
      <dl>
        <dt>Is this safe for everyone?</dt>
        <dd>We include important contraindications: if you are pregnant, have seizure disorders, or unmanaged bipolar/psychosis, please consult your primary provider before attending. Full guidance on the Help page.</dd>
        <dt>Want longer or private work?</dt>
        <dd><a href="private-sessions.html">Private sessions</a> and bespoke small gatherings are available.</dd>
      </dl>
      <p class="more-link"><a href="faq.html">See full FAQ</a></p>
    </section>

    <section class="book-cta">
      <h3 class="section-title">Ready to reserve?</h3>
      <p>Pick a thoughtful way back into rest — select a seat, bring a little comfort, show up as you are.</p>
      <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </section>
  </main>

  <footer class="site-footer">
    <div class="contact">
      <p>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a> • Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
    </div>
    <p class="copyright">© <span id="year"></span> {{BUSINESS_NAME}}</p>
  </footer>

  <div id="exercise-modal" class="modal" aria-hidden="true" role="dialog" aria-label="Guided practice">
    <div class="modal-shell">
      <button id="modal-close" class="modal-close" aria-label="Close practice">✕</button>
      <div class="modal-body">
        <div class="modal-tabs" role="tablist">
          <button class="tab active" data-tab="breath" role="tab" aria-selected="true">Breathing</button>
          <button class="tab" data-tab="journ" role="tab" aria-selected="false">Journaling</button>
        </div>
        <div class="panel active" id="panel-breath" role="tabpanel">
          <h4>Short breathing sequence</h4>
          <div id="breath-visual" class="breath-visual" aria-hidden="true"></div>
          <p id="breath-instruction" class="breath-instruction" aria-live="polite">Press start to begin a guided breathing cycle.</p>
          <div class="modal-actions">
            <button id="start-breath" class="btn">Start</button>
            <button id="stop-breath" class="btn btn-outline">Stop</button>
          </div>
        </div>
        <div class="panel" id="panel-journ" role="tabpanel">
          <h4>Brief journaling + intention</h4>
          <p class="prompt">Prompt — Name three small things you noticed today.</p>
          <textarea id="journ-area" placeholder="Write a line or two..." rows="5"></textarea>
          <div class="modal-actions">
            <button id="start-journ" class="btn">Start 3-minute timer</button>
            <button id="stop-journ" class="btn btn-outline">Stop</button>
          </div>
          <div id="journ-timer" class="journ-timer" aria-live="polite"></div>
        </div>
      </div>
    </div>
  </div>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
